import type { EngineInterface, On } from 'claude-code';
import { parseFileRef } from './core/types.ts';
import { isWindowsPath, type Engine } from './host.ts';
import { PANE_ID, PANE_TITLE, renderPane, type PaneElements } from './pane.ts';
import {
  actions,
  bindEngine,
  ensureContent,
  focusRow,
  handleScroll,
  model,
  noteSize,
  openTarget,
  refresh,
  resetSession,
  scheduleRefresh,
  setFocusSide,
  setShown,
} from './model.ts';

const COMMAND = 'files';

let engine: Engine | null = null;

function engineOf($: EngineInterface, sessionCwd: string): Engine {
  return {
    cwd: () => sessionCwd,
    isWindows: isWindowsPath(sessionCwd),
    list: (path) => $.fs.list(path),
    read: (path) => $.fs.read(path),
    exists: (path) => $.fs.exists(path),
    run: (argv, init) => $.process.run(argv, init),
    after: (ms, fn) => $.clock.after(ms, fn),
    storeGet: (key) => $.store.get(key),
    storeSet: (key, value) => $.store.set(key, value),
    invalidate: () => $.ui.invalidate('ui.render'),
  };
}

async function boot($: EngineInterface): Promise<Engine> {
  if (engine !== null) return engine;
  const sessionCwd = await $.session.cwd();
  engine = engineOf($, sessionCwd);
  bindEngine(engine, sessionCwd);
  return engine;
}

/**
 * The file viewer mod: `/files [path[:line]]` opens the pane, the pane draws
 * from `model.ts`'s single state object, and every edit or shell command
 * schedules a refresh of the tree and the open file.
 */
export function register(on: On, options?: Record<string, unknown>): void {

  on('session.start', async ($, e, next) => {
    resetSession(e.cwd);
    engine = engineOf($, e.cwd);
    bindEngine(engine, e.cwd);
    try {
      await $.command.register({
        name: COMMAND,
        description: 'Open the git-aware file viewer (tree, diff, markdown, code)',
        argumentHint: '[path[:line]]',
        immediate: true,
      });
    } catch {
      // Another plugin already owns /files; leave its registration standing.
    }
    scheduleRefresh();
    return next(e);
  });

  on('command.run', { command: COMMAND }, async ($, e) => {
    await boot($);
    const ref = parseFileRef(e.args);
    await refresh();
    if (ref.path !== '') await openTarget(ref);
    const opened = (await $.ui.open({
      id: PANE_ID,
      title: PANE_TITLE,
      focus: true,
      closeOnEscape: true,
    })) as { isPlaced?: boolean } | undefined;
    if (opened?.isPlaced === false) {
      await $.ui.close({ id: PANE_ID });
      return { text: 'Files: the pane is waiting for a wider terminal.' };
    }
    setShown(true);
    return {};
  }).catch(async () => ({ text: 'file viewer: could not open the pane' }));

  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId !== PANE_ID) return next(e);
    await boot($);
    setShown(true);
    const elements = (await $.ui.resolve(e)) as unknown as PaneElements;
    const size = { bodyColumns: e.props.bodyColumns, bodyRows: e.props.scroll.bodyRows };
    noteSize(size);
    ensureContent();
    return renderPane(elements, model(), size, actions);
  }).catch(async ($, e) => {
    const elements = (await $.ui.resolve(e)) as unknown as PaneElements;
    return elements.Box({
      children: [elements.Text({ children: ['file viewer: this drawing failed'] })],
    });
  });

  on('ui.focus', { component: 'Pane', requestId: PANE_ID }, ($, e, next) => {
    const key = e.element;
    if (typeof key === 'string' && key.startsWith('row:')) {
      setFocusSide('tree');
      focusRow(key.slice(4));
    } else if (typeof key === 'string') {
      setFocusSide('toolbar');
    }
    return next(e);
  }).catch(($, e, next) => next(e));

  on('ui.scroll', { requestId: PANE_ID }, ($, e) => {
    handleScroll(e.by, e.bodyRows, e.pointer?.column);
    return {};
  }).catch(($, e, next) => next(e));

  on('ui.close', { id: PANE_ID }, async ($, e, next) => {
    const result = await next(e);
    setShown(false);
    return result;
  }).catch(($, e, next) => next(e));

  on('tool.call', { tool: ['Edit', 'Write', 'NotebookEdit', 'Bash', 'PowerShell'] }, async ($, e, next) => {
    try {
      return await next(e);
    } finally {
      scheduleRefresh();
    }
  }).catch(($, e, next) => next(e));
}

files.hooks/core/types.ts:
/**
 * Platform-agnostic contracts for the file viewer.
 * Ported from herdr-file-viewer (Rust) — see ARCHITECTURE.md for the mapping.
 *
 * Rules:
 * - All paths are repo-root-relative, POSIX-style ('src/main.rs'), except where noted.
 * - Pure data only: no I/O, no classes with behavior beyond data.
 * - Adapters (claude-code, codex, opencode, deepseek-harness) import these types;
 *   they must never be changed without updating ARCHITECTURE.md.
 */

/** A file's git status against the working tree (git.rs: Status). */
export type GitStatus = 'Modified' | 'Added' | 'Deleted' | 'Untracked';

/** What a diff and "changed" compare against (git.rs: Baseline). */
export type Baseline = 'HEAD' | 'Base';

/** Whether a tree node is a directory or a file (tree.rs: NodeKind). */
export type NodeKind = 'dir' | 'file';

/** One visible row of the tree (tree.rs: Node). */
export interface TreeNode {
  /** Repo-root-relative path, POSIX separators. For compacted chains, the deepest dir. */
  path: string;
  kind: NodeKind;
  depth: number;
  expanded: boolean;
  /** Per-file git status for tree markers; undefined = clean. */
  status?: GitStatus;
  /** Dir only: any file under it has a git status. Always false for files. */
  dirDirty: boolean;
  /** Display override when not the path's final component (compacted chain label). */
  label?: string;
}

/** The facts view policy needs about a file — no I/O (view_policy.rs: FileDescriptor). */
export interface FileDescriptor {
  /** Repo-root-relative path. */
  path: string;
  isMarkdown: boolean;
  isChanged: boolean;
  /** Cached git status says deleted → no content to render. */
  isDeleted: boolean;
}

/** Which rendering the content pane shows (view_policy.rs: ViewMode). */
export type ViewMode = 'renderedMarkdown' | 'diff' | 'fullDiff' | 'syntaxContent';

/** Which policy changed files use for their automatic initial view (ChangedFileView). */
export type ChangedFileView = 'diff' | 'content';

/** A directory listing entry produced by Host.listDir. */
export interface DirEntry {
  /** Entry name within its directory (no separator). */
  name: string;
  kind: NodeKind;
  /** Present for files when the host knows it. */
  size?: number;
}

/** Result of a git invocation; degraded to exitCode -1 when git is unavailable. */
export interface RunResult {
  exitCode: number;
  stdout: string;
  stderr: string;
}

/**
 * The I/O surface core logic needs. Adapters implement this on top of their host
 * (claude-code: $.fs / $.process.run; codex/opencode: node:fs / child_process;
 * dsh: fs + child_process). Core never imports node:fs or spawns processes itself.
 */
export interface Host {
  /** Session working directory (absolute). */
  cwd(): string;
  /** true on Windows — drives null-device and path handling. */
  isWindows: boolean;
  /** List one directory level. Relative paths resolve against cwd(). Missing dir → []. */
  listDir(relPath: string): Promise<DirEntry[]>;
  /** Read a UTF-8 text file (adapters cap at 4 MiB; oversized → throw). */
  readText(relPath: string): Promise<string>;
  /** True when the path exists (file or dir). */
  exists(relPath: string): Promise<boolean>;
  /**
   * Run a read-only git command in the given absolute dir, e.g.
   * runGit(dir, ['status','--porcelain=v1','-z','-uall']).
   * Adapters MUST pass git safety flags (see git.ts SAFE_GIT_FLAGS) and MUST NOT
   * use a shell. Failure/non-repo → { exitCode: -1, stdout: '', stderr }.
   * Timeout: 30s default.
   */
  runGit(dir: string, args: string[]): Promise<RunResult>;
}

/** A parsed `path:line` reference (for opening files at a line). */
export interface FileRef {
  path: string;
  line?: number;
}

/** Parse "src/app.rs:42" / "src/app.rs" → FileRef. Pure. */
export function parseFileRef(input: string): FileRef {
  const m = /^(.*?)(?::(\d+))?$/.exec(input.trim())!;
  const path = m[1] ?? '';
  const line = m[2] ? Number(m[2]) : undefined;
  return line === undefined ? { path } : { path, line };
}

