import type { DirEntry, Host, RunResult } from './core/types.ts';
import { SAFE_GIT_ENV, SAFE_GIT_FLAGS } from './core/git.ts';

/** One `$.fs.list` entry, in the shape the mods API answers with. */
export interface FsEntryLike {
  name: string;
  kind: 'file' | 'dir' | 'other';
  size: number;
  isLink: boolean;
}

/**
 * The mods API, reached through closures `register.ts` builds over `$`.
 * Hooks and timers hand this object around; only `register.ts` may touch `$`,
 * which is why nothing here takes `$` as an argument.
 */
export interface Engine {
  cwd(): string;
  isWindows: boolean;
  list(path: string): Promise<FsEntryLike[]>;
  read(path: string): Promise<string>;
  exists(path: string): Promise<boolean>;
  run(argv: string[], init?: { cwd?: string; env?: Record<string, string> }): Promise<RunResult>;
  after(ms: number, fn: () => void): { cancel(): void };
  storeGet(key: string): Promise<unknown>;
  storeSet(key: string, value: unknown): Promise<void>;
  invalidate(): void;
}

/** True for `C:/x`, `C:\x` or a UNC path — drives `SAFE_GIT_FLAGS`. */
export function isWindowsPath(path: string): boolean {
  return /^[A-Za-z]:[\\/]/.test(path) || path.startsWith('\\\\');
}

function errorText(err: unknown): string {
  if (err instanceof Error) return err.message;
  return String(err);
}

/**
 * The core `Host` over an `Engine`. Core paths are repo-root-relative and
 * POSIX; this is where they become absolute paths for `$.fs`, and where every
 * git call picks up `SAFE_GIT_FLAGS` / `SAFE_GIT_ENV`.
 *
 * `root` is the repo root (or the session cwd outside a repository).
 */
export function createHost(engine: Engine, root: string): Host {
  const base = root.replace(/\/+$/, '');
  const abs = (relPath: string): string => {
    const rel = relPath.replace(/\\/g, '/').replace(/^\.\//, '');
    return rel === '' || rel === '.' ? base : `${base}/${rel}`;
  };

  return {
    cwd: () => engine.cwd(),
    isWindows: engine.isWindows,

    async listDir(relPath: string): Promise<DirEntry[]> {
      try {
        const entries = await engine.list(abs(relPath));
        return entries.map((entry) => ({
          name: entry.name,
          kind: entry.kind === 'dir' ? ('dir' as const) : ('file' as const),
          size: entry.size,
        }));
      } catch {
        return [];
      }
    },

    async readText(relPath: string): Promise<string> {
      return engine.read(abs(relPath));
    },

    async exists(relPath: string): Promise<boolean> {
      try {
        return await engine.exists(abs(relPath));
      } catch {
        return false;
      }
    },

    async runGit(dir: string, args: string[]): Promise<RunResult> {
      try {
        return await engine.run(['git', ...SAFE_GIT_FLAGS(engine.isWindows), ...args], {
          cwd: dir,
          env: SAFE_GIT_ENV,
        });
      } catch (err) {
        return { exitCode: -1, stdout: '', stderr: errorText(err) };
      }
    },
  };
}

files.hooks/pane.ts:
import type { RenderElement } from 'claude-code';
import type {
  Baseline,
  ChangedFileView,
  FileDescriptor,
  NodeKind,
  TreeNode,
  ViewMode,
} from './core/types.ts';
import { applicableModes, defaultMode } from './core/view_policy.ts';

/** The pane's id: `$.ui.open`, `ui.render`, `ui.scroll` and `ui.focus` all key on it. */
export const PANE_ID = 'file-viewer';

/** The pane's tab title. */
export const PANE_TITLE = 'Files';

/** The hard cap `Code.source` and `Markdown.text` impose on one element. */
export const TEXT_LIMIT = 10000;

/** One drawing pass: everything the pane knows about its own geometry. */
export interface PaneSize {
  bodyColumns: number;
  bodyRows: number;
}

/** The rows and columns each part of the pane may take. */
export interface Layout {
  treeColumns: number;
  treeRows: number;
  treeWindowRows: number;
  contentRows: number;
}

/** Which side of the split the tree sits on; the content takes the other. */
export type LayoutSide = 'tree-left' | 'tree-right';

/** The data the drawing reads. `model.ts` owns the instance. */
export interface Model {
  rows: readonly TreeNode[];
  selectedPath?: string;
  selectedKind?: NodeKind;
  treeStart: number;
  contentStart: number;
  contentLines: readonly string[];
  contentKind: 'none' | 'source' | 'diff';
  contentPath?: string;
  notice?: string;
  viewMode: ViewMode;
  baseline: Baseline;
  changedView: ChangedFileView;
  changedOnly: boolean;
  layoutSide: LayoutSide;
  isRepo: boolean;
  isFindOpen: boolean;
  findQuery: string;
  status: string;
  /** The tree root's basename — the tree column's header line (herdr border title). */
  rootName: string;
  /** Current git branch; undefined outside a repo / on a detached HEAD. */
  branch?: string;
  /** Which region was touched last (herdr focus → border highlight). */
  focusSide: 'tree' | 'content' | 'toolbar';
}

/** The callbacks the drawing wires to its controls. */
export interface PaneActions {
  onRowPress(path: string, kind: NodeKind): void;
  onToggleFind(): void;
  onInputFind(value: string): void;
  onSubmitFind(value: string): void;
  onCycleView(): void;
  onNextChanged(): void;
  onPrevChanged(): void;
  onCycleBaseline(): void;
  onToggleChangedOnly(): void;
  onToggleLayout(): void;
  onRefresh(): void;
}

type El = (props: any) => RenderElement;

/** The elements `$.ui.resolve(e)` hands over, narrowed to what the pane draws. */
export interface PaneElements {
  Box: El;
  Text: El;
  Button: El;
  Input: El;
  Code: El;
  Markdown: El;
}

const TOOLBAR_ROWS = 1;
const STATUS_ROWS = 1;
const BORDER_ROWS = 2;
/** Rows the tree/content columns need beyond border + their header line. */
const MIN_SIDE_ROWS = 4;
/** Border colours (herdr border_style): focused accent vs idle dim. */
const FOCUS_BORDER = 'promptBorder';
const IDLE_BORDER = 'inactive';

export function clamp(value: number, low: number, high: number): number {
  return value < low ? low : value > high ? high : value;
}

/** How tall and wide each pane region may be for one `ui.render`. */
export function layoutOf(size: PaneSize): Layout {
  const sideRows = Math.max(MIN_SIDE_ROWS, size.bodyRows - TOOLBAR_ROWS - STATUS_ROWS);
  const treeRows = sideRows;
  // Border (2) + the root-name header line the tree column now draws inside it.
  const treeWindowRows = Math.max(1, treeRows - BORDER_ROWS - 1);
  // The content column borders itself too: border (2) + the file header line.
  const contentRows = Math.max(1, sideRows - BORDER_ROWS - 1);
  let treeColumns = Math.round(size.bodyColumns * 0.3);
  treeColumns = clamp(treeColumns, 16, 44);
  treeColumns = Math.min(treeColumns, Math.max(12, size.bodyColumns - 24));
  return { treeColumns, treeRows, treeWindowRows, contentRows };
}

function baseName(path: string): string {
  const at = path.lastIndexOf('/');
  return at === -1 ? path : path.slice(at + 1);
}

/**
 * One-character git marker (herdr presenter status_marker): files carry their
 * status letter; a directory containing a change carries `●` (was a `~` name
 * suffix — herdr puts the glyph in its own column so it survives color loss).
 */
export function statusMark(row: TreeNode): string {
  if (row.kind === 'dir') return row.dirDirty ? '●' : ' ';
  switch (row.status) {
    case 'Modified':
      return 'M';
    case 'Added':
      return 'A';
    case 'Deleted':
      return 'D';
    case 'Untracked':
      return '?';
    default:
      return ' ';
  }
}

/**
 * Marker-cell colour (herdr row_color): modified/deleted and dirty dirs red,
 * added/untracked green — theme keys so the person's palette wins.
 */
export function markerColor(row: TreeNode): string | undefined {
  if (row.kind === 'dir') return row.dirDirty ? 'error' : undefined;
  switch (row.status) {
    case 'Modified':
    case 'Deleted':
      return 'error';
    case 'Added':
    case 'Untracked':
      return 'success';
    default:
      return undefined;
  }
}

/** The pressable marker cell: selection slot + status glyph + padding (4 columns). */
export function markerCell(row: TreeNode, isSelected: boolean): string {
  return (isSelected ? '❯ ' : '  ') + statusMark(row) + ' ';
}

/**
 * The name cell: 2-space-per-depth indent, expansion caret (files reserve the
 * caret's width too — herdr #130, so siblings at one depth line up), name.
 */
export function rowName(row: TreeNode): string {
  const indent = '  '.repeat(Math.max(0, row.depth));
  const caret = row.kind === 'dir' ? (row.expanded ? '▾ ' : '▸ ') : '  ';
  return indent + caret + (row.label ?? baseName(row.path));
}

/** The whole row as one string (tests + opencode's byte-compatible copy). */
export function rowLabel(row: TreeNode, isSelected: boolean): string {
  return markerCell(row, isSelected) + rowName(row);
}

/** Trim text to the element cap, leaving the engine's truncation note at the tail. */
export function fitText(text: string, limit = TEXT_LIMIT): string {
  if (text.length <= limit) return text;
  const note = '\n… [truncated]';
  return text.slice(0, Math.max(0, limit - note.length)) + note;
}

/** The view a file opens in, honouring a caller's override when the policy allows it. */
export function resolveMode(
  fd: FileDescriptor,
  pref: ChangedFileView,
  override?: ViewMode,
): ViewMode {
  if (fd.isDeleted) return 'diff';
  const modes = applicableModes(fd, pref);
  if (override !== undefined && modes.includes(override)) return override;
  return defaultMode(fd, pref);
}

/** The next view in the file's own cycle (`v`). */
export function cycleMode(fd: FileDescriptor, pref: ChangedFileView, current: ViewMode): ViewMode {
  const modes = fd.isDeleted
    ? applicableModes(fd, pref).filter((mode) => mode === 'diff' || mode === 'fullDiff')
    : applicableModes(fd, pref);
  if (modes.length === 0) return 'diff';
  const at = modes.indexOf(current);
  if (at === -1) return modes[0] as ViewMode;
  return modes[(at + 1) % modes.length] as ViewMode;
}

const HUNK_RE = /^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/;

function isFileHeader(line: string): boolean {
  return (
    line.startsWith('diff --git') ||
    line.startsWith('index ') ||
    line.startsWith('--- ') ||
    line.startsWith('+++ ') ||
    line.startsWith('new file') ||
    line.startsWith('deleted file') ||
    line.startsWith('old mode') ||
    line.startsWith('new mode') ||
    line.startsWith('similarity index') ||
    line.startsWith('rename ') ||
    line.startsWith('Binary files') ||
    line.startsWith('\\ No newline')
  );
}

function isHunkHeader(line: string): boolean {
  return HUNK_RE.test(line);
}

function isHeaderLine(line: string): boolean {
  return isFileHeader(line) || isHunkHeader(line);
}

/** True when the text parses as unified-diff hunks, as `Code({ format: 'diff' })` needs. */
export function looksLikeDiff(text: string): boolean {
  if (!text.includes('@@')) return false;
  let hunks = 0;
  for (const line of text.split('\n')) {
    if (isHunkHeader(line)) {
      hunks += 1;
      continue;
    }
    if (line === '' || isFileHeader(line)) continue;
    if (line.startsWith(' ') || line.startsWith('+') || line.startsWith('-')) continue;
    return false;
  }
  return hunks > 0;
}

function countLine(line: string, counts: { ctx: number; add: number; del: number }): void {
  if (line.startsWith(' ')) counts.ctx += 1;
  else if (line.startsWith('+')) counts.add += 1;
  else if (line.startsWith('-')) counts.del += 1;
  else if (line === '') counts.ctx += 1;
}

function hunkHeader(srcStart: number, tgtStart: number, counts: { ctx: number; add: number; del: number }): string {
  return `@@ -${srcStart},${counts.ctx + counts.del} +${tgtStart},${counts.ctx + counts.add} @@`;
}

/**
 * Cut `lines[from, to)` as a diff that still parses: the window's first hunk
 * header is rewritten to the line numbers and counts the slice really holds, so
 * scrolling a diff can land anywhere without `Code({ format: 'diff' })` refusing.
 */
export function sliceDiff(lines: readonly string[], from: number, to: number): string {
  const start = clamp(from, 0, lines.length);
  const end = clamp(to, start, lines.length);
  if (start === 0) return lines.slice(0, end).join('\n');

  const out: string[] = [];
  let i = start;
  while (i < end) {
    const line = lines[i] as string;
    if (isHunkHeader(line)) {
      const match = HUNK_RE.exec(line);
      const counts = { ctx: 0, add: 0, del: 0 };
      let j = i + 1;
      while (j < end && !isHeaderLine(lines[j] as string)) {
        countLine(lines[j] as string, counts);
        j += 1;
      }
      out.push(hunkHeader(Number(match?.[1] ?? 1), Number(match?.[2] ?? 1), counts));
      for (let k = i + 1; k < j; k += 1) out.push(lines[k] as string);
      i = j;
      continue;
    }
    if (isFileHeader(line)) {
      out.push(line);
      i += 1;
      continue;
    }
    let governing = -1;
    for (let k = start - 1; k >= 0; k -= 1) {
      if (isHunkHeader(lines[k] as string)) {
        governing = k;
        break;
      }
    }
    if (governing === -1) {
      for (let k = start; k < end; k += 1) out.push(lines[k] as string);
      break;
    }
    const match = HUNK_RE.exec(lines[governing] as string);
    const before = { ctx: 0, add: 0, del: 0 };
    for (let k = governing + 1; k < start; k += 1) countLine(lines[k] as string, before);
    const counts = { ctx: 0, add: 0, del: 0 };
    let j = start;
    while (j < end && !isHeaderLine(lines[j] as string)) {
      countLine(lines[j] as string, counts);
      j += 1;
    }
    out.push(
      hunkHeader(
        Number(match?.[1] ?? 1) + before.ctx + before.del,
        Number(match?.[2] ?? 1) + before.ctx + before.add,
        counts,
      ),
    );
    for (let k = start; k < j; k += 1) out.push(lines[k] as string);
    i = j;
  }
  return out.join('\n');
}

function modeLabel(mode: ViewMode): string {
  switch (mode) {
    case 'diff':
      return 'diff';
    case 'fullDiff':
      return 'full diff';
    case 'renderedMarkdown':
      return 'markdown';
    default:
      return 'code';
  }
}

function headerText(m: Model, from: number, to: number): string {
  const parts = [m.contentPath ?? '(nothing selected)', modeLabel(m.viewMode)];
  if (m.contentKind !== 'none') {
    const total = m.contentLines.length;
    parts.push(m.contentKind === 'diff' ? `${from + 1}-${to}/${total}` : `L${from + 1}-${to}/${total}`);
    if (m.contentKind === 'diff') parts.push(`vs ${m.baseline}`);
  }
  return parts.join(' · ');
}

function statusText(m: Model, first: number, last: number): string {
  const parts: string[] = [];
  if (m.rows.length === 0) parts.push('0 rows');
  else parts.push(`${first}-${last}/${m.rows.length} rows`);
  parts.push(m.isRepo ? `base ${m.baseline}` : 'no git repo');
  // herdr tree bottom border: the current branch (omitted when detached/no repo).
  if (m.branch !== undefined && m.branch !== '') parts.push(m.branch);
  if (m.changedOnly) parts.push('changed only');
  if (m.status !== '') parts.push(m.status);
  return parts.join(' · ');
}

function contentBody(ui: PaneElements, m: Model, from: number, to: number): RenderElement {
  if (m.contentKind === 'none') {
    const props: Record<string, unknown> = { children: [m.notice ?? ''], wrap: 'truncate-end' };
    if (m.notice !== undefined) props.color = 'warning'; // herdr notices strip
    else props.dimColor = true;
    return ui.Text(props);
  }
  const visible = m.contentLines.slice(from, to);
  if (m.contentKind === 'diff') {
    const text = fitText(sliceDiff(m.contentLines, from, to));
    return looksLikeDiff(text)
      ? ui.Code({ source: text, format: 'diff', path: m.contentPath, wrap: 'truncate-end' })
      : ui.Code({ source: text, format: 'source', path: m.contentPath, startLine: from + 1, wrap: 'truncate-end' });
  }
  const text = fitText(visible.join('\n'));
  if (m.viewMode === 'renderedMarkdown') return ui.Markdown({ text });
  return ui.Code({ source: text, path: m.contentPath, startLine: from + 1, wrap: 'truncate-end' });
}

function toolbar(ui: PaneElements, m: Model, actions: PaneActions): RenderElement {
  if (m.isFindOpen) {
    return ui.Input({
      key: 'find',
      label: 'find',
      placeholder: 'file name…',
      value: m.findQuery,
      submitLabel: 'go',
      autoFocus: true,
      onInput: (value: string) => actions.onInputFind(value),
      onSubmit: (value: string) => actions.onSubmitFind(value),
    });
  }
  const key = (name: string, label: string, onPress: () => void): RenderElement =>
    ui.Button({ key: 'tb-' + name, label, hotkey: name, plain: true, onPress });
  return ui.Box({
    flexDirection: 'row',
    columnGap: 1,
    children: [
      key('f', 'find', actions.onToggleFind),
      key('v', 'view', actions.onCycleView),
      key('n', 'next', actions.onNextChanged),
      key('p', 'prev', actions.onPrevChanged),
      key('b', m.baseline === 'HEAD' ? 'base HEAD' : 'base Base', actions.onCycleBaseline),
      key('c', m.changedOnly ? 'all files' : 'changed', actions.onToggleChangedOnly),
      key('l', m.layoutSide === 'tree-left' ? 'tree|file' : 'file|tree', actions.onToggleLayout),
      key('r', 'reload', actions.onRefresh),
    ],
  });
}

/** Build the pane's element tree from the model and the size of this pass. */
export function renderPane(
  ui: PaneElements,
  m: Model,
  size: PaneSize,
  actions: PaneActions,
): RenderElement {
  const layout = layoutOf(size);
  const start = clamp(m.treeStart, 0, Math.max(0, m.rows.length - layout.treeWindowRows));
  const windowRows = m.rows.slice(start, start + layout.treeWindowRows);

  // Rows split into a coloured marker cell (herdr row_color) + a pressable
  // name Button — Button is a leaf and cannot carry colour, so the marker
  // (selection slot + M/A/D/?/●) lives in an adjacent Text.
  const treeChildren: RenderElement[] = windowRows.map((row) => {
    const isSelected = row.path === m.selectedPath;
    const markerProps: Record<string, unknown> = { children: [markerCell(row, isSelected)] };
    const color = markerColor(row);
    if (color !== undefined) markerProps.color = color;
    const nameProps: Record<string, unknown> = {
      key: 'row:' + row.path,
      label: rowName(row),
      plain: true,
      dimColor: row.kind === 'dir',
      onPress: () => actions.onRowPress(row.path, row.kind),
    };
    if (isSelected) nameProps.autoFocus = true;
    return ui.Box({
      flexDirection: 'row',
      children: [ui.Text(markerProps), ui.Button(nameProps)],
    });
  });
  if (windowRows.length === 0) {
    treeChildren.push(ui.Text({ children: ['(empty)'], dimColor: true }));
  }

  const from = clamp(m.contentStart, 0, Math.max(0, m.contentLines.length));
  const to = clamp(from + layout.contentRows, from, m.contentLines.length);
  const first = m.rows.length === 0 ? 0 : start + 1;
  const last = m.rows.length === 0 ? 0 : start + windowRows.length;
  const treeFocus = m.focusSide === 'tree';
  const contentFocus = m.focusSide === 'content';

  return ui.Box({
    flexDirection: 'column',
    children: [
      toolbar(ui, m, actions),
      ui.Box({
        flexDirection: m.layoutSide === 'tree-right' ? 'row-reverse' : 'row',
        columnGap: 1,
        children: [
          ui.Box({
            width: layout.treeColumns,
            height: layout.treeRows,
            borderStyle: 'single',
            borderColor: treeFocus ? FOCUS_BORDER : IDLE_BORDER,
            flexDirection: 'column',
            children: [
              // herdr tree border title: the root directory's basename.
              ui.Text({ children: [m.rootName === '' ? 'Files' : m.rootName], dimColor: true, wrap: 'truncate-end' }),
              ...treeChildren,
            ],
          }),
          ui.Box({
            flexDirection: 'column',
            flexGrow: 1,
            borderStyle: 'single',
            borderColor: contentFocus ? FOCUS_BORDER : IDLE_BORDER,
            children: [
              ui.Text({ children: [headerText(m, from, to)], dimColor: true, wrap: 'truncate-end' }),
              contentBody(ui, m, from, to),
            ],
          }),
        ],
      }),
      // herdr's reversed status bar: branch · baseline · filter · notice.
      ui.Text({ children: [statusText(m, first, last)], inverse: true, wrap: 'truncate-end' }),
    ],
  });
}

files.hooks/model.ts:
import type { FileRef, GitStatus, Host, NodeKind, TreeNode } from './core/types.ts';
import { createTreeState, listRows, nextChanged, toggle, type TreeState } from './core/tree.ts';
import { describeFile } from './core/view_policy.ts';
import { fuzzyFilter } from './core/fuzzy.ts';
import {
  changedSet,
  currentBranch,
  defaultBaseline,
  fileDiff,
  status as gitStatus,
} from './core/git.ts';
import { createHost, type Engine } from './host.ts';
import {
  cycleMode,
  layoutOf,
  resolveMode,
  type Model,
  type PaneActions,
  type PaneSize,
} from './pane.ts';

const REDRAW_MS = 120;
const REFRESH_MS = 150;
const CONTENT_MS = 90;
const MAX_CONTENT_CHARS = 200000;
const LINE_CONTEXT = 10;
const HIDE_HIDDEN = true;
const NUL = String.fromCharCode(0);
const CONTROL = new RegExp('[\\u0000-\\u0008\\u000b\\u000c\\u000e-\\u001f\\u007f]', 'g');

const EMPTY: Model = {
  rows: [],
  treeStart: 0,
  contentStart: 0,
  contentLines: [],
  contentKind: 'none',
  viewMode: 'syntaxContent',
  baseline: 'HEAD',
  changedView: 'diff',
  changedOnly: false,
  layoutSide: 'tree-left',
  isRepo: false,
  isFindOpen: false,
  findQuery: '',
  status: '',
  rootName: '',
  focusSide: 'toolbar',
};

let engine: Engine | null = null;
let cwd = '';
let repoRoot = '';
let isRepo = false;
let host: Host | null = null;
let tree: TreeState = createTreeState('');
let statusMap = new Map<string, GitStatus>();
/** Baseline changed-set (herdr changed_filter): fallback markers + `c` source. */
let changedMap = new Map<string, GitStatus>();
let m: Model = { ...EMPTY };
let shown = false;
let size: PaneSize = { bodyColumns: 80, bodyRows: 24 };

let refreshTimer: { cancel(): void } | null = null;
let redrawTimer: { cancel(): void } | null = null;
let contentTimer: { cancel(): void } | null = null;
let refreshing = false;
let refreshQueued = false;
let contentGeneration = 0;
let pendingLine: number | undefined;
let prefsKey = '';

export function toPosix(path: string): string {
  return path.replace(/\\/g, '/');
}

export function normalizeRel(path: string): string {
  const out: string[] = [];
  for (const part of path.split('/')) {
    if (part === '' || part === '.') continue;
    if (part === '..') {
      const last = out[out.length - 1];
      if (out.length > 0 && last !== '..') out.pop();
      else out.push('..');
    } else {
      out.push(part);
    }
  }
  return out.join('/');
}

function isAbsolutePath(path: string): boolean {
  return path.startsWith('/') || /^[A-Za-z]:[\\/]/.test(path) || path.startsWith('\\\\');
}

function relativeFrom(base: string, target: string): string {
  const from = base.replace(/\/+$/, '');
  const to = target.replace(/\/+$/, '');
  if (to === from) return '';
  if (from !== '' && to.startsWith(from + '/')) return to.slice(from.length + 1);
  return '';
}

/**
 * Resolve a `/files` argument to a repo-root-relative POSIX path.
 * Relative arguments resolve against the session cwd; absolute ones must sit
 * under the repo root. Null when the path is outside the repository.
 */
export function resolveRepoRelPath(input: string, sessionCwd: string, root: string): string | null {
  const raw = toPosix(input.trim());
  const from = toPosix(sessionCwd);
  const base = toPosix(root);
  if (raw === '' || base === '') return null;
  if (isAbsolutePath(raw)) {
    if (raw === base) return '';
    if (raw.startsWith(base + '/')) return normalizeRel(raw.slice(base.length + 1));
    return null;
  }
  const cwdRel = relativeFrom(base, from);
  return normalizeRel(cwdRel === '' ? raw : `${cwdRel}/${raw}`);
}

function errorText(err: unknown): string {
  if (err instanceof Error) return err.message;
  return String(err);
}

function sanitize(text: string): string {
  return text.replace(/\r\n?/g, '\n').replace(CONTROL, '');
}

function storeKey(name: string): string {
  return `file-viewer:${repoRoot}:${name}`;
}

export function bindEngine(next: Engine, sessionCwd: string): void {
  engine = next;
  if (sessionCwd !== '') cwd = toPosix(sessionCwd);
}

export function resetSession(sessionCwd: string): void {
  engine = null;
  cwd = sessionCwd === '' ? '' : toPosix(sessionCwd);
  repoRoot = '';
  isRepo = false;
  host = null;
  tree = createTreeState('');
  statusMap = new Map();
  changedMap = new Map();
  m = { ...EMPTY };
  shown = false;
  size = { bodyColumns: 80, bodyRows: 24 };
  refreshTimer?.cancel();
  refreshTimer = null;
  redrawTimer?.cancel();
  redrawTimer = null;
  contentTimer?.cancel();
  contentTimer = null;
  refreshing = false;
  refreshQueued = false;
  contentGeneration += 1;
  pendingLine = undefined;
  prefsKey = '';
}

export function model(): Model {
  return m;
}

export function setShown(value: boolean): void {
  shown = value;
}

function redraw(): void {
  if (!engine || redrawTimer !== null) return;
  redrawTimer = engine.after(REDRAW_MS, () => {
    redrawTimer = null;
    engine?.invalidate();
  });
}

export function scheduleRefresh(): void {
  if (!engine) return;
  refreshTimer?.cancel();
  refreshTimer = engine.after(REFRESH_MS, () => {
    refreshTimer = null;
    void refresh().catch(() => undefined);
  });
}

function ensureVisible(): void {
  const layout = layoutOf(size);
  const at = m.rows.findIndex((row) => row.path === m.selectedPath);
  let start = m.treeStart;
  if (at >= 0) {
    if (at < start) start = at;
    else if (at >= start + layout.treeWindowRows) start = at - layout.treeWindowRows + 1;
  }
  const maxStart = Math.max(0, m.rows.length - layout.treeWindowRows);
  start = start < 0 ? 0 : start > maxStart ? maxStart : start;
  if (start !== m.treeStart) m = { ...m, treeStart: start };
}

export function noteSize(next: PaneSize): void {
  size = next;
  ensureVisible();
}

async function ensureRepo(): Promise<void> {
  if (repoRoot !== '' || !engine) return;
  repoRoot = cwd === '' ? '/' : cwd;
  const probe = createHost(engine, repoRoot);
  try {
    const answer = await probe.runGit(cwd, ['rev-parse', '--show-toplevel']);
    const top = answer.stdout.trim();
    if (answer.exitCode === 0 && top !== '') {
      repoRoot = toPosix(top);
      isRepo = true;
    }
  } catch {
    isRepo = false;
  }
  host = createHost(engine, repoRoot);
  tree = createTreeState('');
  m = { ...m, rootName: baseNameOf(repoRoot === cwd ? cwd : repoRoot) };
}

function baseNameOf(path: string): string {
  const clean = path.replace(/\/+$/, '');
  const at = clean.lastIndexOf('/');
  return at === -1 ? clean : clean.slice(at + 1);
}

async function loadPrefs(): Promise<void> {
  if (!engine || prefsKey === repoRoot) return;
  prefsKey = repoRoot;
  try {
    const baseline = await engine.storeGet(storeKey('baseline'));
    if (baseline === 'HEAD' || baseline === 'Base') {
      m = { ...m, baseline };
    } else if (host && isRepo) {
      // herdr default_baseline: no stored preference → context-smart (AC-14/15).
      m = { ...m, baseline: await defaultBaseline(host, repoRoot) };
    }
    const changedOnly = await engine.storeGet(storeKey('changedOnly'));
    if (typeof changedOnly === 'boolean') m = { ...m, changedOnly };
    const changedView = await engine.storeGet(storeKey('changedView'));
    if (changedView === 'diff' || changedView === 'content') m = { ...m, changedView };
    const layout = await engine.storeGet(storeKey('layout'));
    if (layout === 'tree-left' || layout === 'tree-right') m = { ...m, layoutSide: layout };
  } catch {
    m = { ...m, status: 'preferences unavailable' };
  }
}

async function savePref(name: string, value: unknown): Promise<void> {
  try {
    await engine?.storeSet(storeKey(name), value);
  } catch {
    m = { ...m, status: 'preference not saved' };
  }
}

/** Marker/policy status for a path: working-tree status wins, baseline set fills in. */
function statusOf(path: string): GitStatus | undefined {
  return statusMap.get(path) ?? changedMap.get(path);
}

/** Track which column was touched last (herdr focus → border highlight). */
export function setFocusSide(side: Model['focusSide']): void {
  if (m.focusSide === side) return;
  m = { ...m, focusSide: side };
  redraw();
}

async function rebuildRows(): Promise<void> {
  if (!host) return;
  try {
    const rows = await listRows(host, tree, statusMap, {
      changedOnly: m.changedOnly,
      hideHidden: HIDE_HIDDEN,
      changedSet: changedMap,
    });
    m = { ...m, rows };
  } catch (err) {
    m = { ...m, rows: [], status: 'tree unavailable: ' + errorText(err) };
  }
}

export async function refresh(): Promise<void> {
  if (refreshing) {
    refreshQueued = true;
    return;
  }
  refreshing = true;
  try {
    await ensureRepo();
    if (!host) return;
    let next = new Map<string, GitStatus>();
    try {
      next = await gitStatus(host, repoRoot);
    } catch {
      next = new Map();
      m = { ...m, status: 'git unavailable' };
    }
    statusMap = next;
    await loadPrefs();
    // Baseline changed-set (herdr refresh_git_state): marker fallback + `c` source.
    try {
      changedMap = isRepo ? await changedSet(host, repoRoot, m.baseline) : new Map();
    } catch {
      changedMap = new Map();
    }
    let branch: string | undefined;
    try {
      branch = isRepo ? await currentBranch(host, repoRoot) : undefined;
    } catch {
      branch = undefined;
    }
    await rebuildRows();
    ensureVisible();
    m = { ...m, isRepo, branch };
    if (shown && m.selectedKind === 'file' && m.selectedPath !== undefined) scheduleContent();
  } catch (err) {
    m = { ...m, rows: [], status: 'refresh failed: ' + errorText(err) };
  } finally {
    refreshing = false;
    redraw();
    if (refreshQueued) {
      refreshQueued = false;
      scheduleRefresh();
    }
  }
}

function scheduleContent(): void {
  if (!engine) return;
  contentTimer?.cancel();
  const path = m.selectedPath;
  const line = pendingLine;
  pendingLine = undefined;
  contentTimer = engine.after(CONTENT_MS, () => {
    contentTimer = null;
    void loadContent(path, line).catch(() => undefined);
  });
}

async function loadContent(path: string | undefined, line: number | undefined): Promise<void> {
  if (!host || path === undefined || m.selectedPath !== path) return;
  const generation = ++contentGeneration;
  try {
    if (m.viewMode === 'diff' || m.viewMode === 'fullDiff') {
      const text = await fileDiff(host, repoRoot, path, m.baseline, {
        fullContext: m.viewMode === 'fullDiff',
      });
      if (generation !== contentGeneration) return;
      if (text.trim() === '') {
        m = {
          ...m,
          contentKind: 'none',
          contentLines: [],
          contentStart: 0,
          notice: `no changes vs ${m.baseline}`,
        };
        redraw();
        return;
      }
      const lines = sanitize(text).split('\n');
      const start =
        line === undefined ? 0 : Math.max(0, Math.min(line - 1 - LINE_CONTEXT, lines.length - 1));
      m = { ...m, contentKind: 'diff', contentLines: lines, contentStart: start, notice: undefined };
      redraw();
      return;
    }
    const text = await host.readText(path);
    if (generation !== contentGeneration) return;
    if (text.includes(NUL)) {
      m = { ...m, contentKind: 'none', contentLines: [], contentStart: 0, notice: 'binary file' };
      redraw();
      return;
    }
    const clipped = sanitize(text).slice(0, MAX_CONTENT_CHARS);
    const lines = clipped.split('\n');
    const start =
      line === undefined ? 0 : Math.max(0, Math.min(line - 1 - LINE_CONTEXT, lines.length - 1));
    m = { ...m, contentKind: 'source', contentLines: lines, contentStart: start, notice: undefined };
  } catch (err) {
    if (generation !== contentGeneration) return;
    m = {
      ...m,
      contentKind: 'none',
      contentLines: [],
      contentStart: 0,
      notice: `cannot read ${path}: ${errorText(err)}`,
      status: 'read failed',
    };
  }
  redraw();
}

export function selectPath(path: string, kind: NodeKind, line?: number): void {
  const changed = m.selectedPath !== path;
  tree = { ...tree, selected: { path, kind } };
  m = { ...m, selectedPath: path, selectedKind: kind };
  if (kind !== 'file') {
    m = {
      ...m,
      contentKind: 'none',
      contentLines: [],
      contentStart: 0,
      contentPath: undefined,
      notice: 'directory',
    };
    ensureVisible();
    redraw();
    return;
  }
  if (changed || line !== undefined) {
    const fd = describeFile(path, statusOf(path));
    const mode =
      line !== undefined && !fd.isDeleted
        ? fd.isMarkdown
          ? ('renderedMarkdown' as const)
          : ('syntaxContent' as const)
        : resolveMode(fd, m.changedView, undefined);
    m = {
      ...m,
      viewMode: mode,
      contentKind: 'none',
      contentLines: [],
      contentStart: 0,
      contentPath: path,
      notice: undefined,
    };
  }
  pendingLine = line;
  scheduleContent();
  ensureVisible();
  redraw();
}

function moveSelection(delta: number): void {
  if (m.rows.length === 0) return;
  const found = m.rows.findIndex((row) => row.path === m.selectedPath);
  const at = found < 0 ? 0 : found;
  const target = at + delta;
  const index = target < 0 ? 0 : target >= m.rows.length ? m.rows.length - 1 : target;
  const row = m.rows[index] as TreeNode;
  selectPath(row.path, row.kind);
}

export function focusRow(path: string): void {
  const at = m.rows.findIndex((row) => row.path === path);
  if (at < 0) return;
  const layout = layoutOf(size);
  const bottom = m.treeStart + layout.treeWindowRows - 1;
  if (at === bottom && at < m.rows.length - 1) m = { ...m, treeStart: m.treeStart + 1 };
  else if (at === m.treeStart && m.treeStart > 0) m = { ...m, treeStart: m.treeStart - 1 };
  const row = m.rows[at] as TreeNode;
  if (m.selectedPath !== path) selectPath(row.path, row.kind);
}

function scrollContent(by: number, contentRows: number): void {
  const maxStart = Math.max(0, m.contentLines.length - contentRows);
  const start = m.contentStart + by;
  const next = start < 0 ? 0 : start > maxStart ? maxStart : start;
  if (next !== m.contentStart) m = { ...m, contentStart: next };
  redraw();
}

export function handleScroll(by: number, bodyRows: number, pointerColumn?: number): void {
  const layout = layoutOf({ bodyColumns: size.bodyColumns, bodyRows });
  const overTree =
    pointerColumn !== undefined &&
    (m.layoutSide === 'tree-right'
      ? pointerColumn >= size.bodyColumns - layout.treeColumns
      : pointerColumn < layout.treeColumns);
  if (pointerColumn !== undefined) setFocusSide(overTree ? 'tree' : 'content');
  if (overTree) moveSelection(by);
  else scrollContent(by, layout.contentRows);
}

/** Load the selected file's content when a drawing asks for text that isn't there yet. */
export function ensureContent(): void {
  if (contentTimer !== null) return;
  if (m.selectedKind !== 'file' || m.selectedPath === undefined) return;
  if (m.contentKind !== 'none' || m.notice !== undefined || m.contentLines.length > 0) return;
  scheduleContent();
}

async function toggleDir(path: string): Promise<void> {
  tree = toggle(tree, path);
  tree = { ...tree, selected: { path, kind: 'dir' } };
  m = {
    ...m,
    selectedPath: path,
    selectedKind: 'dir',
    contentKind: 'none',
    contentLines: [],
    contentStart: 0,
    contentPath: undefined,
    notice: 'directory',
  };
  await rebuildRows();
  ensureVisible();
  redraw();
}

async function reveal(path: string): Promise<void> {
  const parts = path.split('/');
  const expanded = new Set(tree.expanded);
  let acc = '';
  for (let i = 0; i < parts.length - 1; i += 1) {
    acc = acc === '' ? (parts[i] as string) : `${acc}/${parts[i] as string}`;
    expanded.add(acc);
  }
  tree = { ...tree, expanded };
  if (m.changedOnly && !statusOf(path)) {
    m = { ...m, changedOnly: false };
    await savePref('changedOnly', false);
  }
  await rebuildRows();
}

async function submitFind(value: string): Promise<void> {
  const query = value.trim();
  m = { ...m, isFindOpen: false, findQuery: '' };
  if (query === '') {
    redraw();
    return;
  }
  const files = m.rows.filter((row) => row.kind === 'file');
  const hits = fuzzyFilter(query, files, (row) => row.path);
  const target = hits.length === 0 ? '' : (hits[0]?.item.path ?? '');
  if (target === '') {
    m = { ...m, status: `no match: ${query}` };
    redraw();
    return;
  }
  await reveal(target);
  const row = m.rows.find((candidate) => candidate.path === target);
  if (row) selectPath(row.path, row.kind);
  else m = { ...m, status: `not found: ${target}` };
  redraw();
}

async function cycleBaseline(): Promise<void> {
  m = { ...m, baseline: m.baseline === 'HEAD' ? 'Base' : 'HEAD' };
  await savePref('baseline', m.baseline);
  // herdr `b`: markers and the changed-only filter are baseline-dependent too.
  if (host && isRepo) {
    try {
      changedMap = await changedSet(host, repoRoot, m.baseline);
    } catch {
      changedMap = new Map();
    }
    await rebuildRows();
    ensureVisible();
  }
  if (m.selectedKind === 'file') {
    pendingLine = undefined;
    scheduleContent();
  }
  redraw();
}

async function toggleChangedOnly(): Promise<void> {
  m = { ...m, changedOnly: !m.changedOnly };
  await savePref('changedOnly', m.changedOnly);
  await rebuildRows();
  ensureVisible();
  redraw();
}

async function toggleLayout(): Promise<void> {
  m = { ...m, layoutSide: m.layoutSide === 'tree-left' ? 'tree-right' : 'tree-left' };
  await savePref('layout', m.layoutSide);
  redraw();
}

function cycleView(): void {
  const path = m.selectedPath;
  if (path === undefined || m.selectedKind !== 'file') return;
  const fd = describeFile(path, statusOf(path));
  m = { ...m, viewMode: cycleMode(fd, m.changedView, m.viewMode) };
  pendingLine = undefined;
  scheduleContent();
  redraw();
}

function jumpChanged(direction: 1 | -1): void {
  const target = nextChanged(m.rows as TreeNode[], m.selectedPath, direction);
  if (target === undefined) {
    m = { ...m, status: 'no changed files' };
    redraw();
    return;
  }
  const row = m.rows.find((candidate) => candidate.path === target);
  if (row) selectPath(row.path, row.kind);
}

/** Select what `/files path[:line]` asked for, opening collapsed folders on the way. */
export async function openTarget(ref: FileRef): Promise<void> {
  const rel = resolveRepoRelPath(ref.path, cwd, repoRoot);
  if (rel === null || rel === '') {
    m = { ...m, status: `outside repository: ${ref.path}` };
    redraw();
    return;
  }
  if (HIDE_HIDDEN && rel.split('/').some((part) => part.startsWith('.'))) {
    m = { ...m, status: `hidden path: ${rel}` };
    redraw();
    return;
  }
  await reveal(rel);
  const row = m.rows.find((candidate) => candidate.path === rel);
  if (!row) {
    m = { ...m, status: `not found: ${rel}` };
    redraw();
    return;
  }
  selectPath(row.path, row.kind, ref.line);
}

export const actions: PaneActions = {
  onRowPress: (path, kind) => {
    if (kind === 'dir') void toggleDir(path).catch(() => undefined);
    else selectPath(path, 'file');
  },
  onToggleFind: () => {
    m = { ...m, isFindOpen: !m.isFindOpen, findQuery: '' };
    redraw();
  },
  onInputFind: (value) => {
    m = { ...m, findQuery: value };
  },
  onSubmitFind: (value) => {
    void submitFind(value).catch(() => undefined);
  },
  onCycleView: cycleView,
  onNextChanged: () => jumpChanged(1),
  onPrevChanged: () => jumpChanged(-1),
  onCycleBaseline: () => {
    void cycleBaseline().catch(() => undefined);
  },
  onToggleChangedOnly: () => {
    void toggleChangedOnly().catch(() => undefined);
  },
  onToggleLayout: () => {
    void toggleLayout().catch(() => undefined);
  },
  onRefresh: () => {
    void refresh().catch(() => undefined);
  },
};

